using System.Globalization;
using OOP_FINAL_CSharp.Models;
using OOP_FINAL_CSharp.Models.Enums;
using OOP_FINAL_CSharp.Models.Policy;
using OOP_FINAL_CSharp.Services;
using OOP_FINAL_CSharp.Data;


/// <summary>
/// Interactive terminal console for the in-memory hotel booking system.
/// IDs are generated by HotelService when creating customers, room groups,
/// utilities, and rooms; existing IDs are only entered when selecting records.
/// </summary>
internal static class Program
{
    private static readonly HotelService Hotel = new();
    private static bool _running = true;

    private static void Main()
    {
        // Inside Main()
        Database.Initialize();

        Console.WriteLine("==============================================");
        Console.WriteLine("       HOTEL BOOKING SYSTEM - C# CONSOLE");
        Console.WriteLine("==============================================");
        Console.WriteLine("Date/time format: yyyy-MM-dd HH:mm (24-hour)");
        Console.WriteLine("IDs are generated automatically when records are created.");

        while (_running)
        {
            PrintMenu();
            var choice = ReadInt("Choose an option: ");
            Console.WriteLine();

            try
            {
                switch (choice)
                {
                    case 1: AddCustomer(); break;
                    case 2: ListCustomers(); break;
                    case 3: AddRoomGroup(); break;
                    case 4: AddUtility(); break;
                    case 5: ListRoomGroupsAndUtilities(); break;
                    case 6: AddRoom(); break;
                    case 7: ListRooms(availableOnly: false); break;
                    case 8: ListRooms(availableOnly: true); break;
                    case 9: BookRoom(); break;
                    case 10: ListContracts(); break;
                    case 11: FindOngoingContracts(); break;
                    case 12: CheckIn(); break;
                    case 13: UseUtility(); break;
                    case 14: CheckOut(); break;
                    case 15: PreviewBill(); break;
                    case 16: CreateInvoice(); break;
                    case 17: ListInvoices(); break;
                    case 18: RunReports(); break;
                    case 0:
                        _running = false;
                        Console.WriteLine("Goodbye!");
                        break;
                    default:
                        Console.WriteLine("Invalid menu option. Choose 0-18.");
                        break;
                }
            }
            catch (Exception ex) when (ex is ArgumentException or InvalidOperationException)
            {
                Console.WriteLine($"Operation failed: {ex.Message}");
            }

            if (_running)
            {
                Console.WriteLine();
                Console.Write("Press Enter to return to the menu...");
                Console.ReadLine();
                Console.WriteLine();
            }
        }
    }

    private static void PrintMenu()
    {
        Console.WriteLine("\n=============== MAIN MENU ===============");
        Console.WriteLine(" CUSTOMERS");
        Console.WriteLine("  1. Add customer (auto ID)");
        Console.WriteLine("  2. List customers");
        Console.WriteLine(" ROOM SETUP");
        Console.WriteLine("  3. Add room group / category (auto ID)");
        Console.WriteLine("  4. Add utility (auto ID) and assign to room groups");
        Console.WriteLine("  5. List room groups and utilities");
        Console.WriteLine("  6. Add room (auto ID)");
        Console.WriteLine("  7. List all rooms");
        Console.WriteLine("  8. List available rooms only");
        Console.WriteLine(" BOOKING OPERATIONS");
        Console.WriteLine("  9. Book a room");
        Console.WriteLine(" 10. List contracts");
        Console.WriteLine(" 11. Find customer's ongoing contracts");
        Console.WriteLine(" 12. Check in");
        Console.WriteLine(" 13. Use utility");
        Console.WriteLine(" 14. Check out");
        Console.WriteLine(" BILLING");
        Console.WriteLine(" 15. Preview bill");
        Console.WriteLine(" 16. Create invoice");
        Console.WriteLine(" 17. List invoices");
        Console.WriteLine(" REPORTS");
        Console.WriteLine(" 18. Run all 10 reports (LINQ + lambda)");
        Console.WriteLine("  0. Exit");
        Console.WriteLine("=========================================");
    }

    private static void AddCustomer()
    {
        Console.WriteLine("--- Add customer ---");
        var name = ReadNonBlank("Full name: ");
        var phone = ReadNonBlank("Phone number: ");
        var cccd = ReadNonBlank("CCCD / ID number: ");
        var type = ReadEnum("Customer type", Enum.GetValues<CustomerType>());

        var customer = Hotel.CreateCustomer(name, phone, cccd, type);
        Console.WriteLine($"Customer added. Generated ID: {customer.Id}");
    }

    private static void ListCustomers()
    {
        Console.WriteLine("--- Customers ---");
        if (Hotel.Customers.Count == 0)
        {
            Console.WriteLine("No customers yet.");
            return;
        }

        foreach (var customer in Hotel.Customers)
            Console.WriteLine($"{customer.Id} | {customer.Name} | phone: {customer.PhoneNumber} | type: {customer.Type}");
    }

    private static void AddRoomGroup()
    {
        Console.WriteLine("--- Add room group / category ---");
        var name = ReadNonBlank("Room-group name: ");
        var type = ReadEnum("Room type", Enum.GetValues<RoomType>());
        var overstayFee = ReadNonNegativeDouble("Overstay fee per day: ");
        var capacityFee = ReadNonNegativeDouble("Fee per extra person over capacity: ");

        var group = Hotel.CreateRoomGroup(name, type, new FeePolicy(overstayFee, capacityFee));
        Console.WriteLine($"Room group added. Generated ID: {group.GroupId}");
    }

    private static void AddUtility()
    {
        Console.WriteLine("--- Add utility ---");
        var name = ReadNonBlank("Utility name: ");
        var price = ReadNonNegativeDouble("Price per use: ");
        var utility = Hotel.CreateUtility(name, price);
        Console.WriteLine($"Utility created. Generated ID: {utility.UtilityId}");

        if (Hotel.RoomGroups.Count == 0)
        {
            Console.WriteLine("No room groups yet. Create a room group first, then assign this utility later if needed.");
            return;
        }

        Console.WriteLine("Assign the utility to one or more room groups.");
        while (ReadYesNo("Assign to a room group? (y/n): "))
        {
            ListRoomGroupsShort();
            var groupId = ReadNonBlank("Existing room-group ID: ");
            var group = Hotel.FindRoomGroup(groupId);
            if (group is null)
            {
                Console.WriteLine("Room group not found. Try again.");
                continue;
            }

            if (!group.Utilities.Contains(utility))
                group.AddUtility(utility);

            if (ReadYesNo("Is this utility free for this room group? (y/n): "))
                utility.AddFreeGroup(group);

            Console.WriteLine($"Assigned {utility.UtilityId} to {group.GroupId}.");
        }
    }

    private static void ListRoomGroupsShort()
    {
        if (Hotel.RoomGroups.Count == 0)
        {
            Console.WriteLine("No room groups yet.");
            return;
        }

        foreach (var group in Hotel.RoomGroups)
            Console.WriteLine($"{group.GroupId} | {group.GroupName} | type: {group.Type}");
    }

    private static void ListRoomGroupsAndUtilities()
    {
        Console.WriteLine("--- Room groups and utilities ---");
        if (Hotel.RoomGroups.Count == 0)
        {
            Console.WriteLine("No room groups yet.");
            return;
        }

        foreach (var group in Hotel.RoomGroups)
        {
            Console.WriteLine($"\n{group.GroupId} | {group.GroupName} | type: {group.Type} | " +
                              $"overstay/day: {group.Fee.OverStayFeePerDay:F2} | " +
                              $"over-capacity/person: {group.Fee.OverMaxCapacityFee:F2}");
            if (group.Utilities.Count == 0)
            {
                Console.WriteLine("  No utilities assigned.");
                continue;
            }

            foreach (var utility in group.Utilities)
                Console.WriteLine($"  {utility.UtilityId} | {utility.UtilityName} | price {utility.UtilityPrice:F2} | " +
                                  $"free here: {(utility.IsFreeForGroup(group) ? "yes" : "no")}");
        }
    }

    private static void AddRoom()
    {
        Console.WriteLine("--- Add room ---");
        if (Hotel.RoomGroups.Count == 0)
        {
            Console.WriteLine("Create a room group first (menu option 3).");
            return;
        }

        var location = ReadNonBlank("Room location / floor: ");
        var capacity = ReadPositiveInt("Maximum room capacity: ");
        var price = ReadNonNegativeDouble("Price per calendar day: ");
        ListRoomGroupsShort();
        var groupId = ReadNonBlank("Existing room-group ID: ");
        var group = Hotel.FindRoomGroup(groupId);
        if (group is null)
        {
            Console.WriteLine("Room group not found; room was not added.");
            return;
        }

        var room = Hotel.CreateRoom(location, capacity, group, RoomStatus.AVAILABLE, price);
        Console.WriteLine($"Room added. Generated ID: {room.RoomId} | Initial status: AVAILABLE.");
    }

    private static void ListRooms(bool availableOnly)
    {
        Console.WriteLine(availableOnly ? "--- Available rooms ---" : "--- All rooms ---");
        var rooms = Hotel.Rooms
            .Where(room => !availableOnly || room.Status == RoomStatus.AVAILABLE)
            .ToList();

        if (rooms.Count == 0)
        {
            Console.WriteLine(availableOnly ? "No rooms currently available." : "No rooms yet.");
            return;
        }

        foreach (var room in rooms)
            Console.WriteLine($"{room.RoomId} | type: {room.RoomType,-9} | group: {room.RoomGroup.GroupName} | " +
                              $"capacity: {room.RoomCapacity} | price/day: {room.RoomPrice:F2} | status: {room.Status}");
    }

    private static void BookRoom()
    {
        Console.WriteLine("--- Book a room ---");
        if (Hotel.Customers.Count == 0 || Hotel.Rooms.Count == 0)
        {
            Console.WriteLine("Add at least one customer and one room first.");
            return;
        }

        ListRooms(availableOnly: true);
        var roomId = ReadNonBlank("Existing room ID: ");
        var customerId = ReadNonBlank("Existing customer ID: ");
        if (Hotel.FindRoom(roomId) is null || Hotel.FindCustomer(customerId) is null)
        {
            Console.WriteLine("Room or customer ID not found.");
            return;
        }

        var start = ReadDateTime("Booking start (yyyy-MM-dd HH:mm): ");
        var end = ReadDateTime("Booking end   (yyyy-MM-dd HH:mm): ");
        var previousCount = Hotel.Contracts.Count;
        if (!Hotel.BookRoom(roomId, customerId, start, end))
        {
            Console.WriteLine("Booking failed.");
            return;
        }

        if (Hotel.Contracts.Count > previousCount)
            Console.WriteLine($"Created contract ID: {Hotel.Contracts[^1].ContractId}");
    }

    private static void ListContracts()
    {
        Console.WriteLine("--- Contracts ---");
        if (Hotel.Contracts.Count == 0)
        {
            Console.WriteLine("No contracts yet.");
            return;
        }

        foreach (var contract in Hotel.Contracts)
        {
            Console.WriteLine($"{contract.ContractId} | customer: {contract.Customer.Id} ({contract.Customer.Name}) | " +
                              $"room: {contract.Room.RoomId} ({contract.Room.RoomType}) | " +
                              $"{contract.StartTime:yyyy-MM-dd HH:mm} -> {contract.EndTime:yyyy-MM-dd HH:mm} | " +
                              $"status: {contract.Status} | check-in: {FormatDateTime(contract.CheckInTime)} | " +
                              $"check-out: {FormatDateTime(contract.CheckOutTime)}");
        }
    }

    private static RentalContract? PromptContract()
    {
        var id = ReadNonBlank("Existing contract ID: ");
        var contract = Hotel.FindContractById(id);
        if (contract is null)
            Console.WriteLine("Contract not found.");
        return contract;
    }

    private static void FindOngoingContracts()
    {
        Console.WriteLine("--- Find ongoing contracts by customer ---");
        var customerId = ReadNonBlank("Existing customer ID: ");
        var customer = Hotel.FindCustomer(customerId);
        if (customer is null)
        {
            Console.WriteLine("Customer not found.");
            return;
        }

        var contracts = Hotel.FindOnGoingContractByCustomer(customer);
        if (contracts.Count == 0)
        {
            Console.WriteLine("This customer has no ongoing contracts.");
            return;
        }

        contracts.ForEach(contract => Console.WriteLine(contract));
    }

    private static void CheckIn()
    {
        Console.WriteLine("--- Check in ---");
        var contract = PromptContract();
        if (contract is null) return;

        var time = ReadDateTime("Check-in time (yyyy-MM-dd HH:mm): ");
        var people = ReadPositiveInt("Number of people checking in: ");
        Console.WriteLine(Hotel.CheckIn(contract.ContractId, time, people)
            ? "Check-in successful."
            : "Check-in failed.");
    }

    private static void UseUtility()
    {
        Console.WriteLine("--- Use utility ---");
        if (Hotel.Utilities.Count == 0)
        {
            Console.WriteLine("No utilities yet. Create one first (menu option 4).");
            return;
        }

        var contract = PromptContract();
        if (contract is null) return;

        foreach (var utility in Hotel.Utilities)
            Console.WriteLine($"{utility.UtilityId} | {utility.UtilityName} | {utility.UtilityPrice:F2}");

        var utilityId = ReadNonBlank("Existing utility ID to use: ");
        var item = Hotel.FindUtility(utilityId);
        if (item is null)
        {
            Console.WriteLine("Utility not found.");
            return;
        }

        Console.WriteLine(Hotel.UseUtility(contract.ContractId, item)
            ? "Utility use recorded."
            : "Could not record utility use.");
    }

    private static void CheckOut()
    {
        Console.WriteLine("--- Check out ---");
        var contract = PromptContract();
        if (contract is null) return;

        var time = ReadDateTime("Check-out time (yyyy-MM-dd HH:mm): ");
        Console.WriteLine(Hotel.CheckOut(contract.ContractId, time)
            ? "Check-out successful."
            : "Check-out failed.");
    }

    private static void PreviewBill()
    {
        Console.WriteLine("--- Preview bill ---");
        var contract = PromptContract();
        if (contract is null) return;
        if (contract.CheckOutTime is null)
        {
            Console.WriteLine("The customer has not checked out, so the final bill is not ready.");
            return;
        }

        PrintBillBreakdown(contract);
    }

    private static double PrintBillBreakdown(RentalContract contract)
    {
        var roomFee = Hotel.CalculateRoomFee(contract);
        var overstayFee = Hotel.CalculateOverstayFee(contract);
        var utilityFee = Hotel.CalculateUtilityFee(contract);
        var capacityFee = Hotel.CalculateOverMaxCapacityFee(contract);
        var deposit = roomFee * 0.10;
        var total = roomFee + overstayFee + utilityFee + capacityFee - deposit;

        Console.WriteLine($"Room fee:                 {roomFee:F2}");
        Console.WriteLine($"Overstay fee:             {overstayFee:F2}");
        Console.WriteLine($"Utility fee:              {utilityFee:F2}");
        Console.WriteLine($"Over-capacity fee:        {capacityFee:F2}");
        Console.WriteLine($"Deposit deduction (10%): -{deposit:F2}");
        Console.WriteLine("----------------------------------------");
        Console.WriteLine($"TOTAL DUE:                {total:F2}");
        return total;
    }

    private static void CreateInvoice()
    {
        Console.WriteLine("--- Create invoice ---");
        var contract = PromptContract();
        if (contract is null) return;
        if (contract.CheckOutTime is null)
        {
            Console.WriteLine("Customer must check out before creating an invoice.");
            return;
        }
        if (Hotel.Invoices.Any(invoice => invoice.Contract == contract))
        {
            Console.WriteLine("An invoice already exists for this contract.");
            return;
        }

        Console.WriteLine($"Contract customer: {contract.Customer.Name} ({contract.Customer.Id})");
        Console.WriteLine("Choose payer from the existing customers:");
        ListCustomers();
        var payerId = ReadNonBlank("Payer customer ID: ");
        var payer = Hotel.FindCustomer(payerId);
        if (payer is null)
        {
            Console.WriteLine("Payer not found.");
            return;
        }

        var paymentMethod = ReadEnum("Payment method", Enum.GetValues<PaymentType>());
        var invoice = Hotel.CreateInvoice(contract, payer, paymentMethod);
        if (invoice is null)
        {
            Console.WriteLine("Invoice was not created.");
            return;
        }

        Console.WriteLine($"Invoice created successfully. Invoice ID: {invoice.InvoiceId}");
    }

    private static void ListInvoices()
    {
        Console.WriteLine("--- Invoices ---");
        if (Hotel.Invoices.Count == 0)
        {
            Console.WriteLine("No invoices yet.");
            return;
        }

        foreach (var invoice in Hotel.Invoices)
            Console.WriteLine($"{invoice.InvoiceId} | contract: {invoice.Contract.ContractId} | " +
                              $"payer: {invoice.Payer.Id} ({invoice.Payer.Name}) | payment: {invoice.PaymentType} | " +
                              $"checkout: {FormatDateTime(invoice.Contract.CheckOutTime)} | total: {invoice.Total:F2}");
    }

    private static void RunReports()
    {
        Console.WriteLine("========================================");
        Console.WriteLine("             HOTEL REPORTS");
        Console.WriteLine("========================================");
    }

    private static string ReadLine(string prompt)
    {
        Console.Write(prompt);
        return Console.ReadLine()?.Trim() ?? string.Empty;
    }

    private static string ReadNonBlank(string prompt)
    {
        while (true)
        {
            var value = ReadLine(prompt);
            if (!string.IsNullOrWhiteSpace(value)) return value;
            Console.WriteLine("Value cannot be blank.");
        }
    }

    private static int ReadInt(string prompt)
    {
        while (true)
        {
            var value = ReadLine(prompt);
            if (int.TryParse(value, out var result)) return result;
            Console.WriteLine("Please enter a whole number.");
        }
    }

    private static int ReadPositiveInt(string prompt)
    {
        while (true)
        {
            var value = ReadInt(prompt);
            if (value > 0) return value;
            Console.WriteLine("Value must be greater than zero.");
        }
    }

    private static double ReadNonNegativeDouble(string prompt)
    {
        while (true)
        {
            var value = ReadLine(prompt);
            if (double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var result)
                && double.IsFinite(result) && result >= 0)
                return result;
            Console.WriteLine("Please enter a valid number that is zero or greater (use . for decimals).");
        }
    }

    private static bool ReadYesNo(string prompt)
    {
        while (true)
        {
            var value = ReadLine(prompt).ToLowerInvariant();
            if (value is "y" or "yes") return true;
            if (value is "n" or "no") return false;
            Console.WriteLine("Enter y or n.");
        }
    }

    private static DateTime ReadDateTime(string prompt)
    {
        while (true)
        {
            var value = ReadNonBlank(prompt);
            if (DateTime.TryParseExact(value, "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture,
                    DateTimeStyles.None, out var result))
                return result;
            Console.WriteLine("Invalid date/time. Use yyyy-MM-dd HH:mm, e.g. 2026-10-21 14:30.");
        }
    }

    private static TEnum ReadEnum<TEnum>(string prompt, TEnum[] values) where TEnum : struct, Enum
    {
        Console.WriteLine($"{prompt}:");
        for (var i = 0; i < values.Length; i++)
            Console.WriteLine($"  {i + 1}. {values[i]}");

        while (true)
        {
            var selected = ReadInt("Select number: ");
            if (selected >= 1 && selected <= values.Length)
                return values[selected - 1];
            Console.WriteLine($"Choose a number from 1 to {values.Length}.");
        }
    }

    private static string FormatDateTime(DateTime? value) =>
        value?.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) ?? "-";
}